export async function open(request='',{draftOnly=false,viewMode}={}){if(!panel)create();if(!panel.open){window.JarvisBridge?.stopListening?.();window.JarvisBridge?.stopAudio?.();panel.showModal();}if(viewMode)setSurfaceMode(viewMode);startFace();if(request)$('build-request').value=request;if(request&&!draftOnly)await submit(request);else if(!model){let saved;try{saved=await window.DeviceStore?.get('jarvis-workshop-v1');}catch(_){}try{init3D();setSurfaceMode(surfaceMode);draw();status(saved?'Arbeitsbereich bereit. Ein gesicherter Entwurf ist vorhanden; du kannst ihn ausdrücklich anzeigen oder einen neuen Wunsch beschreiben.':'Arbeitsbereich bereit. Beschreibe, was Jarvis für dich entwerfen soll.');if(saved)$('build-load').disabled=false;}catch(_){status('Für die 3D-Ansicht wird WebGL benötigt.');}}else draw();}

export async function openProject(dimensions={}){await open();const data=await api('/api/workshop/hologram-project',dimensions);await showModel(data);message('assistant',data.reply);setBuildView('guide');}

function openMotif(){const d=document.createElement('dialog');d.style.cssText='padding:12px;background:black;color:white;border:1px solid #4f6;max-width:96vw';const c=document.createElement('canvas');c.width=c.height=600;c.style.cssText='display:block;width:min(80vw,70vh);height:auto;background:black';const close=document.createElement('button');close.textContent='Testmotiv schließen';close.onclick=()=>d.close();d.append(c,close);document.body.append(d);d.showModal();let frame=null;const ctx=c.getContext('2d');function draw(t){if(!d.open)return;ctx.fillStyle='black';ctx.fillRect(0,0,600,600);for(let i=0;i<4;i++){ctx.save();ctx.translate(300,300);ctx.rotate(i*Math.PI/2);ctx.translate(0,-160);ctx.strokeStyle='#79ffe2';ctx.lineWidth=3;ctx.beginPath();const a=t*.0005;for(let n=0;n<5;n++){const angle=n*Math.PI/2+a,x=Math.cos(angle)*40,y=Math.sin(angle)*40;if(!n)ctx.moveTo(x,y);else ctx.lineTo(x,y);}ctx.stroke();ctx.restore();}frame=requestAnimationFrame(draw);}frame=requestAnimationFrame(draw);d.addEventListener('close',()=>{cancelAnimationFrame(frame);d.remove();});}


// A physical build guide is readable without an AI-generated model or WebGL.
let hologramGuide=null,guideRequest=null,guideAudio=null,guideSource=null,guideVoiceEpoch=0;
function stopGuideVoice(){guideVoiceEpoch++;if(guideSource){guideSource.onended=null;try{guideSource.stop();}catch(_){}}guideSource=null;}
async function readHologramStep(text){
 const version=++guideVoiceEpoch;const state=$('hologram-guide-status');
 if(guideSource){guideSource.onended=null;try{guideSource.stop();}catch(_){}}guideSource=null;
 try{
  const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw Error('Dieser Browser unterstützt hier keine Audiowiedergabe.');
  if(!guideAudio||guideAudio.state==='closed')guideAudio=new Audio();await guideAudio.resume();
  if(!token){const session=await fetch('/api/session');if(!session.ok)throw Error('Bitte den Mac verbinden.');token=(await session.json()).token;}
  state.textContent='Thorsten bereitet den Schritt vor …';
  const response=await fetch('/api/natural-voice/speak',{method:'POST',headers:{'Content-Type':'application/json','X-Jarvis-Token':token},body:JSON.stringify({text:text.slice(0,900),preset:'jarvis'})});
  if(!response.ok){let detail='';try{detail=(await response.json()).error||'';}catch(_){}throw Error(detail||'Thorsten ist gerade nicht verfügbar. Du kannst die Anleitung vollständig lesen.');}
  const buffer=await guideAudio.decodeAudioData(await response.arrayBuffer());if(version!==guideVoiceEpoch||!hologramGuide.open)return;
  guideSource=guideAudio.createBufferSource();guideSource.buffer=buffer;guideSource.connect(guideAudio.destination);guideSource.onended=()=>{if(version===guideVoiceEpoch){guideSource=null;state.textContent='Schritt vorgelesen. Wähle den nächsten Schritt.';}};guideSource.start();state.textContent='Thorsten liest den Schritt vor.';
 }catch(e){if(version===guideVoiceEpoch&&hologramGuide.open)state.textContent=e.message;}
}
function createHologramGuide(){
 if(!document.querySelector('link[href="/workshop.css"]')){const style=document.createElement('link');style.rel='stylesheet';style.href='/workshop.css';document.head.append(style);}
 const d=document.createElement('dialog');d.id='hologram-build-guide';d.setAttribute('aria-labelledby','hologram-guide-title');
 d.innerHTML='<header><div><small>JARVIS / BAUANLEITUNG</small><h2 id="hologram-guide-title">Hologramm selbst bauen</h2></div><button type="button" id="hologram-guide-close">Schließen ×</button></header><p id="hologram-guide-summary">Die Anleitung wird geladen …</p><form id="hologram-guide-form"><label>Gesamtbudget · Euro<input id="hologram-guide-budget" type="number" min="1" max="100000" step="0.01" value="40" required></label><label>Schon vorhandene Geräte<input id="hologram-guide-inventory" maxlength="1200" placeholder="Zum Beispiel Display, kleiner Rechner, USB-Kamera"></label><button type="submit" id="hologram-guide-refresh">Angaben übernehmen</button></form><p id="hologram-guide-status" role="status" aria-live="polite"></p><button type="button" id="hologram-guide-mute">Vorlesen stoppen</button><nav id="hologram-guide-nav" aria-label="Abschnitte der Bauanleitung"></nav><figure class="hologram-guide-optics"><svg viewBox="0 0 600 230" role="img" aria-labelledby="hologram-optics-title hologram-optics-desc"><title id="hologram-optics-title">Seitenansicht des Spiegelungsaufbaus</title><desc id="hologram-optics-desc">Ein waagerechtes Display unter einer klaren Scheibe strahlt nach oben. Die Scheibe steht im Winkel von 45 Grad und reflektiert das Licht nach links zum Betrachter. Hinter der Scheibe steht ein dunkler Hintergrund.</desc><defs><marker id="hologram-optics-arrow" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0 0 L7 3 L0 6" fill="#88e6e4"/></marker></defs><rect x="180" y="170" width="160" height="12" rx="4" fill="#88e6e4"/><text x="190" y="208">Display · waagerecht</text><line x1="210" y1="50" x2="310" y2="150" stroke="#d6f3cd" stroke-width="5"/><text x="290" y="47">Klare Scheibe · 45°</text><rect x="430" y="30" width="15" height="140" rx="3" fill="#020805" stroke="#5f755b"/><text x="453" y="65">Dunkler</text><text x="453" y="87">Hintergrund</text><path d="M260 165 V100 H75" fill="none" stroke="#88e6e4" stroke-width="3" marker-end="url(#hologram-optics-arrow)"/><text x="74" y="145">Reflektiertes Licht</text><circle cx="48" cy="100" r="13" fill="none" stroke="#d6f3cd" stroke-width="2"/><text x="20" y="70">Dein Blick →</text></svg><figcaption>Seitenansicht: Das Displaybild wird an der klaren Scheibe zu dir gespiegelt. Die Zeichnung erklärt den Lichtweg; sie ist keine maßstäbliche Zuschnittvorlage.</figcaption></figure><section id="hologram-guide-content"></section><section id="hologram-guide-shopping"><h3>Teile und Voraussetzungen</h3><ul></ul></section><section id="hologram-guide-limits"><h3>Was noch geprüft werden muss</h3><ul></ul></section>';
 document.body.append(d);hologramGuide=d;
 $('hologram-guide-close').onclick=()=>d.close();$('hologram-guide-mute').onclick=()=>{stopGuideVoice();$('hologram-guide-status').textContent='Vorlesen gestoppt.';};
 $('hologram-guide-form').onsubmit=e=>{e.preventDefault();loadHologramGuide();};
 d.addEventListener('close',()=>{guideRequest?.abort();guideRequest=null;stopGuideVoice();if(guideAudio){guideAudio.close().catch(()=>{});guideAudio=null;}});
}
async function loadHologramGuide(){
 guideRequest?.abort();stopGuideVoice();const c=new AbortController();guideRequest=c;const timeout=setTimeout(()=>c.abort(),20000);$('hologram-guide-refresh').disabled=true;$('hologram-guide-status').textContent='Anleitung wird geladen …';
 try{
  const data=await api('/api/workshop/hologram-guide',{budget:Number($('hologram-guide-budget').value),inventory:$('hologram-guide-inventory').value},c.signal);
  if(guideRequest!==c||!hologramGuide.open)return;
  $('hologram-guide-title').textContent=data.title;$('hologram-guide-summary').textContent=data.summary;
  const content=$('hologram-guide-content'),nav=$('hologram-guide-nav');content.replaceChildren();nav.replaceChildren();
  for(const [index,section]of data.sections.entries()){
   const card=document.createElement('section');card.id='hologram-guide-section-'+index;const heading=document.createElement('h3');heading.textContent=section.title;card.append(heading);
   if(section.text){const p=document.createElement('p');p.textContent=section.text;card.append(p);}
   const steps=document.createElement('ol');for(const text of section.steps||[]){const li=document.createElement('li'),p=document.createElement('p'),read=document.createElement('button');p.textContent=text;read.type='button';read.textContent='Mit Thorsten vorlesen';read.onclick=()=>readHologramStep(text);li.append(p,read);steps.append(li);}card.append(steps);content.append(card);
   const jump=document.createElement('button');jump.type='button';jump.textContent=section.title;jump.onclick=()=>card.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});nav.append(jump);
  }
  const shopping=$('hologram-guide-shopping').querySelector('ul');shopping.replaceChildren();for(const part of data.shopping){const li=document.createElement('li');li.textContent=typeof part==='string'?part:[part.item,part.need,part.note].filter(Boolean).join(' · ');shopping.append(li);}
  const limits=$('hologram-guide-limits').querySelector('ul');limits.replaceChildren();for(const text of data.limits){const li=document.createElement('li');li.textContent=text;limits.append(li);}
  $('hologram-guide-status').textContent='Anleitung bereit. Alles ist direkt hier lesbar; zum Vorlesen einen Schritt wählen.';
 }catch(e){if(guideRequest===c&&hologramGuide.open){if(!$('hologram-guide-content').children.length)$('hologram-guide-summary').textContent='Zum ersten Laden der Bauanleitung muss Jarvis am Mac erreichbar sein. Danach bleibt die bereits geladene Anleitung in diesem Fenster lesbar.';$('hologram-guide-status').textContent=e.name==='AbortError'?'Die Anleitung konnte nicht rechtzeitig geladen werden. Prüfe die Verbindung zum Mac und versuche es erneut.':e.message;}}
 finally{clearTimeout(timeout);if(guideRequest===c){guideRequest=null;$('hologram-guide-refresh').disabled=false;}}
}
export async function openHologramGuide({budget=40,inventory=''}={}){
 if(!hologramGuide)createHologramGuide();
 if(!hologramGuide.open){window.JarvisBridge?.stopListening?.();window.JarvisBridge?.stopAudio?.();if(panel)stopListening();else stopVoice();hologramGuide.showModal();}
 $('hologram-guide-budget').value=budget;$('hologram-guide-inventory').value=inventory;
 await loadHologramGuide();
}

function referenceURL(value){try{const url=new URL(value);return url.protocol==='https:'&&!url.username&&!url.password?url.href:null;}catch(_){return null;}}
function createReferencePanel(){
 const box=document.createElement('details');box.id='build-references';box.innerHTML='<summary>Vorlage aus dem Internet</summary><p>Suche nach einem echten Objekt oder einer Bauidee. Gefundene Texte können deinen eigenen Entwurf ergänzen. Die kleine Text-KI sieht dabei keine Bilder und rekonstruiert keine Vorlage exakt.</p><form id="build-reference-search"><label>Objekt oder Idee<input id="build-reference-query" maxlength="400" placeholder="Zum Beispiel Arc-Reaktor Gehäuse Aufbau"></label><button type="submit" id="build-reference-run">Quellen suchen</button></form><p id="build-reference-status" role="status"></p><section id="build-reference-results"></section><form id="build-reference-glb"><label>Vorhandene 3D-Datei · direkter HTTPS-Link auf .glb<input id="build-reference-glb-url" type="url" maxlength="2200" placeholder="https://…/modell.glb"></label><button type="submit">3D-Vorlage ansehen</button><p>Öffnet die vorhandene Modellansicht separat. Eine normale Webseite ist keine 3D-Datei. Vorschau und Nutzung hängen von Datei, Lizenz und Größenlimit ab.</p></form>';
 panel.querySelector('.build-view-head').before(box);$('build-request').maxLength=2400;
 let search=null;
 $('build-reference-search').onsubmit=async e=>{
  e.preventDefault();const query=$('build-reference-query').value.trim();if(!query)return;
  search?.abort();const c=new AbortController();search=c;const timeout=setTimeout(()=>c.abort(),30000);$('build-reference-run').disabled=true;$('build-reference-status').textContent='Öffentliche Quellen werden gesucht …';
  try{
   const data=await api('/api/workshop/research',{query},c.signal);if(search!==c||!panel.open)return;
   const host=$('build-reference-results');host.replaceChildren();
   const excerpt=String(data.reply||'').slice(0,900);if(excerpt){const p=document.createElement('p');p.textContent=excerpt;host.append(p);}
   for(const source of(data.sources||[]).slice(0,3)){
    const url=referenceURL(source.url);if(!url)continue;const card=document.createElement('article'),link=document.createElement('a'),button=document.createElement('button');link.href=url;link.target='_blank';link.rel='noopener noreferrer';link.textContent=String(source.title||'Quelle öffnen').slice(0,150);button.type='button';button.textContent='Als Referenz für Entwurf übernehmen';button.onclick=()=>{
     const sourceText=value=>String(value||'').replace(/[\[\]]/g,c=>c==='['?'(':')').replace(/[\r\n]+/g,' ');const block='[WEBREFERENZ]\nTitel: '+sourceText(source.title).slice(0,100)+'\nURL: '+url.slice(0,300).replace(/\[/g,'%5B').replace(/\]/g,'%5D')+'\nAuszug: '+sourceText(source.snippet||'Kein dieser Quelle zugeordneter Suchauszug verfügbar.').slice(0,300)+'\n[/WEBREFERENZ]';
     const input=$('build-request');const wish=input.value.replace(/\[WEBREFERENZ\][\s\S]*?\[\/WEBREFERENZ\]/g,'').trim();input.value=(block+'\n\n'+wish.slice(0,900)).trim().slice(0,1800);$('build-reference-status').textContent='Referenz im Bauwunsch übernommen. Prüfe den Text und ergänze, was Jarvis daraus entwerfen soll. Der Entwurf wird erst mit deinem Bauauftrag gestartet.';input.focus();
    };card.append(link,button);host.append(card);
   }
   $('build-reference-status').textContent='Ergebnisse sind ungeprüfte Quellen. Lies die Quelle und beschreibe die gewünschte Form; Bilder wurden nicht analysiert.';
  }catch(error){if(search===c&&panel.open)$('build-reference-status').textContent=error.name==='AbortError'?'Die Recherche braucht zu lange. Versuche es erneut.':error.message;}
  finally{clearTimeout(timeout);if(search===c){search=null;$('build-reference-run').disabled=false;}}
 };
 $('build-reference-glb').onsubmit=async e=>{e.preventDefault();const url=referenceURL($('build-reference-glb-url').value.trim());if(!url){$('build-reference-status').textContent='Bitte einen direkten HTTPS-Link auf eine GLB-Datei eingeben.';return;}try{const viewer=await import('/object-viewer.js');await viewer.openReference(url);}catch(error){$('build-reference-status').textContent='3D-Vorlage konnte nicht geöffnet werden: '+error.message;}};
 panel.addEventListener('close',()=>{search?.abort();search=null;$('build-reference-run').disabled=false;});
}
